-- Generated from DHSUD-CAR Records Database.xlsx.
-- Cell values are stored as text to preserve workbook contents and Excel date serials.
-- This workbook export includes credential hashes, salts, and session tokens; protect it as sensitive data.

SET NAMES utf8mb4;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
CREATE DATABASE IF NOT EXISTS `dhsud_car_records` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `dhsud_car_records`;

CREATE TABLE `_spreadsheet_sheets` (`sheet_position` SMALLINT UNSIGNED NOT NULL PRIMARY KEY, `sheet_name` VARCHAR(255) NOT NULL UNIQUE, `source_row_count` INT UNSIGNED NOT NULL, `source_column_count` SMALLINT UNSIGNED NOT NULL, `visibility` VARCHAR(16) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `_spreadsheet_columns` (`sheet_position` SMALLINT UNSIGNED NOT NULL, `source_column` SMALLINT UNSIGNED NOT NULL, `source_header` LONGTEXT NULL, `sql_column` VARCHAR(64) NOT NULL, PRIMARY KEY (`sheet_position`, `source_column`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `_spreadsheet_cell_metadata` (`sheet_position` SMALLINT UNSIGNED NOT NULL, `source_row` INT UNSIGNED NOT NULL, `source_column` SMALLINT UNSIGNED NOT NULL, `cell_type` VARCHAR(12) NOT NULL, `number_format` TEXT NULL, PRIMARY KEY (`sheet_position`, `source_row`, `source_column`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `_spreadsheet_hyperlinks` (`sheet_position` SMALLINT UNSIGNED NOT NULL, `source_row` INT UNSIGNED NOT NULL, `source_column` SMALLINT UNSIGNED NOT NULL, `target` TEXT NOT NULL, `tooltip` TEXT NULL, PRIMARY KEY (`sheet_position`, `source_row`, `source_column`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

